namespace Tripous.Data;

/// <summary>
/// Coordinates database operations for a list table and an item table tree.
/// Tables managed by a TableSet use a single-field primary key: either a string
/// containing a GUID or an integer generated by an auto-increment column or a
/// database generator/sequence. These conventions apply to TableSet operations;
/// other database access mechanisms may use different kinds of keys.
/// Item operations require SQL statements generated by Tripous from application
/// definitions such as TableDef and FieldDef, rather than statements supplied
/// by the application programmer.
/// </summary>
public class TableSet
{
    // ● private fields
    readonly SqlStore fStore;
    readonly MemTable fListTable;
    readonly MemTable fItemTable;
    readonly TableSetFlags fFlags;

    // ● private SQL preparation
    /// <summary>
    /// Prepares missing list SQL when generation is enabled and checks that
    /// every pending list operation has the required statement.
    /// </summary>
    void PrepareListSaveSql(bool HasDeletes, bool HasUpdates, bool HasInserts)
    {
        bool Missing = (HasDeletes && string.IsNullOrWhiteSpace(fListTable.Sqls.DeleteRowSql))
            || (HasUpdates && string.IsNullOrWhiteSpace(fListTable.Sqls.UpdateRowSql))
            || (HasInserts && string.IsNullOrWhiteSpace(fListTable.Sqls.InsertRowSql));
        if (Missing && (fFlags & TableSetFlags.GenerateSql) != 0)
        {
            DbSchema Schema = fStore.Schema;
            Schema.Load();
            DbMetaTable[] Tables = Schema.Tables.Where(Item => string.Equals(Item.Name, fListTable.TableName, StringComparison.OrdinalIgnoreCase)).ToArray();
            if (Tables.Length != 1)
                throw new InvalidOperationException($"Expected one database table named '{fListTable.TableName}', found {Tables.Length}.");
            SqlStatementBuilder.BuildSaveSql(fListTable, Tables[0]);
        }
        if (HasDeletes && string.IsNullOrWhiteSpace(fListTable.Sqls.DeleteRowSql))
            throw new InvalidOperationException($"Table '{fListTable.TableName}' has no delete statement.");
        if (HasUpdates && string.IsNullOrWhiteSpace(fListTable.Sqls.UpdateRowSql))
            throw new InvalidOperationException($"Table '{fListTable.TableName}' has no update statement.");
        if (HasInserts && string.IsNullOrWhiteSpace(fListTable.Sqls.InsertRowSql))
            throw new InvalidOperationException($"Table '{fListTable.TableName}' has no insert statement.");
    }

    // ● private posting
    /// <summary>
    /// Creates parameters from the specified version of a row.
    /// Deleted rows use their original values; other rows use current values.
    /// </summary>
    static SqlParams CreateRowParams(DataRow Row, DataRowVersion Version)
    {
        SqlParams Result = new();
        foreach (DataColumn Column in Row.Table.Columns)
            Result.Add(Column.ColumnName, Row[Column, Version]);
        return Result;
    }
    /// <summary>
    /// Returns whether the type is a supported signed integer key type.
    /// </summary>
    static bool IsIntegerType(Type Type) => Type == typeof(int) || Type == typeof(long);
    /// <summary>
    /// Returns tables in the configured delete order.
    /// </summary>
    IEnumerable<MemTable> GetDeleteOrder(IEnumerable<MemTable> Tables)
        => (fFlags & TableSetFlags.NoCascadeDeletes) != 0
            ? Tables.OrderBy(Table => Table.Level)
            : Tables.OrderByDescending(Table => Table.Level);
    /// <summary>
    /// Posts deleted rows of one table using their original values.
    /// The caller owns the transaction and controls the order of tables.
    /// </summary>
    void PostDeletes(DbTransaction Transaction, MemTable Table, DataRow[] Rows)
    {
        foreach (DataRow Row in Rows)
        {
            if (fStore.ExecSql(Transaction, Table.Sqls.DeleteRowSql, CreateRowParams(Row, DataRowVersion.Original)) == 0)
                throw new InvalidOperationException($"Delete did not affect a row in table '{Table.TableName}'.");
        }
    }
    /// <summary>
    /// Posts modified rows of one table using their current values.
    /// The caller owns the transaction and controls the order of tables.
    /// </summary>
    void PostUpdates(DbTransaction Transaction, MemTable Table, DataRow[] Rows)
    {
        foreach (DataRow Row in Rows)
        {
            if (fStore.ExecSql(Transaction, Table.Sqls.UpdateRowSql, CreateRowParams(Row, DataRowVersion.Current)) == 0)
                throw new InvalidOperationException($"Update did not affect a row in table '{Table.TableName}'.");
        }
    }
    /// <summary>
    /// Posts new rows and obtains generated integer keys in the transaction.
    /// Records previous values for rollback and optionally updates detail keys.
    /// </summary>
    void PostInserts(DbTransaction Transaction, MemTable Table, DataRow[] Rows, List<(DataRow Row, DataColumn Column, object Value)> PreviousIds, bool UpdateDetails = false)
    {
        DataColumn Key = Table.Columns[Table.KeyField];
        bool IntegerKey = IsIntegerType(Key.DataType);
        OidMode Mode = fStore.OidMode;
        foreach (DataRow Row in Rows)
        {
            object PreviousId = Row[Key];
            if (IntegerKey)
            {
                PreviousIds.Add((Row, Key, PreviousId));
                if (Mode == OidMode.Generator)
                    Row[Key] = Convert.ChangeType(fStore.NextId(Transaction, Table.TableName), Key.DataType, System.Globalization.CultureInfo.InvariantCulture);
            }
            if (fStore.ExecSql(Transaction, Table.Sqls.InsertRowSql, CreateRowParams(Row, DataRowVersion.Current)) == 0)
                throw new InvalidOperationException($"Insert did not affect a row in table '{Table.TableName}'.");
            if (IntegerKey && Mode == OidMode.AutoInc)
                Row[Key] = Convert.ChangeType(fStore.LastId(Transaction, Table.TableName), Key.DataType, System.Globalization.CultureInfo.InvariantCulture);
            if (IntegerKey && UpdateDetails && !Equals(PreviousId, Row[Key]))
                UpdateDetailKeys(Table, PreviousId, Row[Key], PreviousIds);
        }
    }
    /// <summary>
    /// Replaces a temporary master key in direct detail rows and records
    /// the previous values so they can be restored after rollback.
    /// </summary>
    void UpdateDetailKeys(MemTable Master, object PreviousId, object NewId, List<(DataRow Row, DataColumn Column, object Value)> PreviousValues)
    {
        foreach (MemTable Detail in Master.Details)
        {
            if (!string.Equals(Detail.MasterField, Master.KeyField, StringComparison.OrdinalIgnoreCase))
                continue;
            DataColumn Column = Detail.Columns[Detail.DetailField];
            foreach (DataRow Row in Detail.Rows)
            {
                if (Row.RowState == DataRowState.Deleted || Row.IsNull(Column) || !Equals(Row[Column], PreviousId))
                    continue;
                PreviousValues.Add((Row, Column, Row[Column]));
                Row[Column] = NewId;
            }
        }
    }

    // ● private validation
    /// <summary>
    /// Checks the item tree, its pending edits and the statements required
    /// for the rows that will be posted.
    /// </summary>
    void CheckItemSaveTables(List<MemTable> Tables)
    {
        fItemTable.CheckTopTableErrors();
        foreach (MemTable Table in Tables)
        {
            if (Table.KeyFields.Length != 1)
                throw new InvalidOperationException($"Table '{Table.TableName}' requires a single key field.");
            if (Table.Master != null && (Table.MasterFields.Length != 1 || Table.DetailFields.Length != 1))
                throw new InvalidOperationException($"Table '{Table.TableName}' requires a single master-detail field pair.");
            DataColumn Key = Table.Columns[Table.KeyField];
            bool IntegerKey = IsIntegerType(Key.DataType);
            if (Key.DataType != typeof(string) && !IntegerKey)
                throw new NotSupportedException($"Table '{Table.TableName}' requires a string, Int32 or Int64 key.");
            foreach (DataRow Row in Table.Rows)
            {
                if (Row.HasVersion(DataRowVersion.Proposed))
                    throw new InvalidOperationException($"Finish editing rows in table '{Table.TableName}' before saving.");
                if (Row.RowState == DataRowState.Deleted && string.IsNullOrWhiteSpace(Table.Sqls.DeleteRowSql))
                    throw new InvalidOperationException($"Table '{Table.TableName}' has no delete statement.");
                if (Row.RowState == DataRowState.Modified)
                {
                    if (string.IsNullOrWhiteSpace(Table.Sqls.UpdateRowSql))
                        throw new InvalidOperationException($"Table '{Table.TableName}' has no update statement.");
                    if (!Equals(Row[Key, DataRowVersion.Original], Row[Key, DataRowVersion.Current]))
                        throw new InvalidOperationException($"Table '{Table.TableName}' cannot change a primary key.");
                }
                if (Row.RowState == DataRowState.Added)
                {
                    if (string.IsNullOrWhiteSpace(Table.Sqls.InsertRowSql))
                        throw new InvalidOperationException($"Table '{Table.TableName}' has no insert statement.");
                    if (IntegerKey && fStore.OidMode == OidMode.None)
                        throw new NotSupportedException("The provider has no integer identifier generation mode.");
                }
            }
        }
    }

    // ● private transaction notifications
    /// <summary>
    /// Raises an item commit transaction-stage notification.
    /// </summary>
    void NotifyTransactionStageCommit(DbTransaction Transaction, TransactionStage Stage, ExecTime Time)
        => TransactionStageCommit?.Invoke(this, new TransactionEventArgs(fStore, Transaction, Stage, Time, null));
    /// <summary>
    /// Raises an item delete transaction-stage notification with the item key.
    /// </summary>
    void NotifyTransactionStageDelete(DbTransaction Transaction, TransactionStage Stage, ExecTime Time, object RowId)
        => TransactionStageDelete?.Invoke(this, new TransactionEventArgs(fStore, Transaction, Stage, Time, RowId));

    // ● private item loading
    /// <summary>
    /// Loads every detail and sub-detail for the master rows in batches,
    /// using the caller's transaction and the framework-generated SELECTs.
    /// </summary>
    void LoadDetails(DbTransaction Transaction, MemTable Master)
    {
        foreach (MemTable Detail in Master.Details)
        {
            if (Master.Rows.Count == 0)
                continue;
            if (Detail.MasterFields == null || Detail.MasterFields.Length != 1 || Detail.DetailFields == null || Detail.DetailFields.Length != 1)
                throw new InvalidOperationException($"Table '{Detail.TableName}' requires a single master-detail field pair.");
            if (string.IsNullOrWhiteSpace(Detail.Sqls.SelectSql))
                throw new InvalidOperationException($"Table '{Detail.TableName}' has no select statement.");

            object[] Values = Master.Rows.Cast<DataRow>()
                .Where(Row => Row.RowState != DataRowState.Deleted && !Row.IsNull(Detail.MasterField))
                .Select(Row => Row[Detail.MasterField]).Distinct().ToArray();
            HashSet<object> ImportedKeys = new();
            for (int Offset = 0; Offset < Values.Length; Offset += 100)
            {
                SqlParams Params = new();
                List<string> Names = new();
                int Count = Math.Min(100, Values.Length - Offset);
                for (int Index = 0; Index < Count; Index++)
                {
                    string Name = $"MasterKey{Index}";
                    Names.Add(SqlProvider.GlobalPrefix + Name);
                    Params.Add(Name, Values[Offset + Index]);
                }
                SelectSql Sql = new(Detail.Sqls.SelectSql);
                // Item tree SQL is generated from definitions and has no independent detail filter.
                Sql.Where = $"{Detail.TableName}.{Detail.DetailField} IN ({string.Join(", ", Names)})";
                using (DataTable Source = fStore.Select(Transaction, Sql.Text, Params))
                {
                    if (!Source.Columns.Contains(Detail.KeyField))
                        throw new InvalidOperationException($"Select for table '{Detail.TableName}' does not return key '{Detail.KeyField}'.");
                    foreach (DataRow Row in Source.Rows)
                    {
                        object Key = Row[Detail.KeyField];
                        if (Key == DBNull.Value)
                            throw new InvalidOperationException($"Select for table '{Detail.TableName}' returned a null key.");
                        if (ImportedKeys.Add(Key))
                            Detail.ImportRow(Row);
                    }
                }
            }
            LoadDetails(Transaction, Detail);
        }
    }

    // ● private item editing
    /// <summary>
    /// Cancels proposed row edits throughout the item tree, starting at details.
    /// </summary>
    void CancelPendingEdits()
    {
        List<MemTable> Tables = fItemTable.GetTreeAsFlatList();
        for (int Index = Tables.Count - 1; Index >= 0; Index--)
        {
            foreach (DataRow Row in Tables[Index].Rows)
            {
                if (Row.HasVersion(DataRowVersion.Proposed))
                    Row.CancelEdit();
            }
        }
    }

    // ● constructor
    /// <summary>
    /// Creates a table set for the specified store, list table and item table.
    /// SQL generation is disabled unless explicitly requested in the flags.
    /// </summary>
    public TableSet(SqlStore Store, MemTable ListTable, MemTable ItemTable, TableSetFlags Flags = TableSetFlags.None)
    {
        ArgumentNullException.ThrowIfNull(Store);
        ArgumentNullException.ThrowIfNull(ListTable);
        ArgumentNullException.ThrowIfNull(ItemTable);
        fStore = Store;
        fListTable = ListTable;
        fItemTable = ItemTable;
        fFlags = Flags;
    }

    // ● list database operations
    /// <summary>
    /// Replaces the list table contents using the supplied or configured SELECT.
    /// Returns the row count on success or the reason the SELECT did not complete.
    /// </summary>
    public TableSetResult ListSelect(string SqlText) => ListSelect(SqlText, new SqlParams());
    /// <summary>
    /// Replaces the list table contents using a SELECT and its parameters.
    /// </summary>
    public TableSetResult ListSelect(string SqlText, SqlParams Params)
    {
        try
        {
            string Text = string.IsNullOrWhiteSpace(SqlText) ? fListTable.Sqls.SelectSql : SqlText;
            if (string.IsNullOrWhiteSpace(Text))
                return new TableSetResult(TableSetResultStatus.ListSelectSqlEmpty, null, null);
            fListTable.EventsDisabled = true;
            try
            {
                int Count = fStore.SelectTo(fListTable, Text, Params);
                return new TableSetResult(TableSetResultStatus.Success, null, null, Count);
            }
            finally
            {
                fListTable.EventsDisabled = false;
            }
        }
        catch (Exception Error)
        {
            return new TableSetResult(TableSetResultStatus.ListSelectFailed, null, Error);
        }
    }
    /// <summary>
    /// Saves changes to the list table in one transaction.
    /// Supports string and provider-generated integer primary keys.
    /// </summary>
    public TableSetResult ListSave()
    {
        bool Committed = false;
        try
        {
            if (fListTable.Rows.Cast<DataRow>().Any(Row => Row.HasVersion(DataRowVersion.Proposed)))
                throw new InvalidOperationException("Finish editing list rows before saving.");
            DataRow[] Deleted = fListTable.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Deleted).ToArray();
            DataRow[] Modified = fListTable.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Modified).ToArray();
            DataRow[] Added = fListTable.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Added).ToArray();
            if (Deleted.Length + Modified.Length + Added.Length == 0)
                return new TableSetResult(TableSetResultStatus.Success, null, null);
            if (fListTable.KeyFields == null || fListTable.KeyFields.Length != 1 || !fListTable.Columns.Contains(fListTable.KeyField))
                throw new InvalidOperationException("ListSave requires a single key field in the list table.");
            DataColumn Key = fListTable.Columns[fListTable.KeyField];
            bool IntegerKey = IsIntegerType(Key.DataType);
            if (Key.DataType != typeof(string) && !IntegerKey)
                throw new NotSupportedException("ListSave requires a string, Int32 or Int64 primary key.");
            OidMode Mode = fStore.OidMode;
            if (IntegerKey && Added.Length > 0 && Mode == OidMode.None)
                throw new NotSupportedException("The provider has no integer identifier generation mode.");
            if (Modified.Any(Row => !Equals(Row[Key, DataRowVersion.Original], Row[Key, DataRowVersion.Current])))
                throw new InvalidOperationException("ListSave cannot change a primary key.");
            PrepareListSaveSql(Deleted.Length > 0, Modified.Length > 0, Added.Length > 0);
            List<(DataRow Row, DataColumn Column, object Value)> PreviousIds = new();
            using (SqlTransactionContext Context = fStore.BeginTransactionContext())
            {
                try
                {
                    PostDeletes(Context.Transaction, fListTable, Deleted);
                    PostUpdates(Context.Transaction, fListTable, Modified);
                    PostInserts(Context.Transaction, fListTable, Added, PreviousIds);
                    Context.Commit();
                    Committed = true;
                }
                catch
                {
                    if (Context.IsActive)
                    {
                        try
                        {
                            Context.Rollback();
                            for (int Index = PreviousIds.Count - 1; Index >= 0; Index--)
                                PreviousIds[Index].Row[PreviousIds[Index].Column] = PreviousIds[Index].Value;
                        }
                        catch
                        {
                            // TODO: Log rollback or identifier restoration failures.
                        }
                    }
                    throw;
                }
            }
            fListTable.AcceptChanges();
            return new TableSetResult(TableSetResultStatus.Success, null, null);
        }
        catch (Exception Error)
        {
            return new TableSetResult(Committed ? TableSetResultStatus.AfterCommitFailed : TableSetResultStatus.ListSaveFailed, null, Error);
        }
    }
    /// <summary>
    /// Rejects pending changes in the list table.
    /// This only affects the in-memory list table; it does not access the database.
    /// </summary>
    public void ListCancel() => fListTable.RejectChanges();


    // ● item database operations
    /// <summary>
    /// Loads one item and its details. Clears the item tree on failure.
    /// </summary>
    public TableSetResult Load(object RowId)
    {
        try
        {
            ProcessEmpty();
            if (RowId == null || RowId == DBNull.Value || (RowId is string Text && string.IsNullOrWhiteSpace(Text)))
                return new TableSetResult(TableSetResultStatus.InvalidId, RowId, null);
            fItemTable.CheckTopTableErrors();
            if (fItemTable.KeyFields.Length != 1)
                throw new InvalidOperationException("The item table requires a single key field.");
            if (string.IsNullOrWhiteSpace(fItemTable.Sqls.SelectRowSql))
                throw new InvalidOperationException($"Table '{fItemTable.TableName}' has no select-row statement.");

            fItemTable.EventsDisabled = true;
            try
            {
                using (SqlTransactionContext Context = fStore.BeginTransactionContext())
                {
                    fStore.SelectTo(Context.Transaction, fItemTable, fItemTable.Sqls.SelectRowSql, new SqlParams().Add(fItemTable.KeyField, RowId));
                    if (fItemTable.Rows.Count > 1)
                        throw new InvalidOperationException($"Select for item table '{fItemTable.TableName}' returned more than one row.");
                    LoadDetails(Context.Transaction, fItemTable);
                    Context.Commit();
                }
                fItemTable.AcceptChangesAll();
            }
            finally
            {
                fItemTable.EventsDisabled = false;
            }
            fItemTable.RefreshDetails();
            return new TableSetResult(fItemTable.Rows.Count == 1 ? TableSetResultStatus.Success : TableSetResultStatus.NotFound, RowId, null);
        }
        catch (Exception Error)
        {
            try { ProcessEmpty(); }
            catch (Exception CleanupError) { Error = new AggregateException(Error, CleanupError); }
            return new TableSetResult(TableSetResultStatus.LoadFailed, RowId, Error);
        }
    }
    /// <summary>
    /// Loads and deletes an item and its detail tree in a transaction.
    /// A post-commit event can fail after the database deletion has completed.
    /// </summary>
    public TableSetResult Delete(object RowId)
    {
        bool Committed = false;
        try
        {
            TableSetResult LoadResult = Load(RowId);
            if (LoadResult.Status != TableSetResultStatus.Success)
                return LoadResult;

            fItemTable.EventsDisabled = true;
            try
            {
                fItemTable.DeleteAll(false);
                NotifyTransactionStageDelete(null, TransactionStage.Start, ExecTime.Before, RowId);
                using (SqlTransactionContext Context = fStore.BeginTransactionContext())
                {
                    DbTransaction Transaction = Context.Transaction;
                    try
                    {
                        NotifyTransactionStageDelete(Transaction, TransactionStage.Start, ExecTime.After, RowId);
                        NotifyTransactionStageDelete(Transaction, TransactionStage.Post, ExecTime.Before, RowId);
                        List<MemTable> Tables = fItemTable.GetTreeAsFlatList();
                        CheckItemSaveTables(Tables);
                        foreach (MemTable Table in GetDeleteOrder(Tables))
                            PostDeletes(Transaction, Table, Table.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Deleted).ToArray());
                        NotifyTransactionStageDelete(Transaction, TransactionStage.Post, ExecTime.After, RowId);
                        NotifyTransactionStageDelete(Transaction, TransactionStage.Commit, ExecTime.Before, RowId);
                        Context.Commit();
                        Committed = true;
                        fItemTable.AcceptChangesAll();
                        NotifyTransactionStageDelete(Transaction, TransactionStage.Commit, ExecTime.After, RowId);
                    }
                    catch
                    {
                        if (Context.IsActive)
                        {
                            try { NotifyTransactionStageDelete(Transaction, TransactionStage.Rollback, ExecTime.Before, RowId); }
                            catch { /* TODO: Log rollback notification failures. */ }
                            bool RolledBack = false;
                            try
                            {
                                Context.Rollback();
                                RolledBack = true;
                            }
                            catch { /* TODO: Log rollback failures. */ }
                            if (RolledBack)
                            {
                                try { NotifyTransactionStageDelete(Transaction, TransactionStage.Rollback, ExecTime.After, RowId); }
                                catch { /* TODO: Log rollback notification failures. */ }
                            }
                        }
                        throw;
                    }
                }
            }
            catch
            {
                if (!Committed)
                {
                    try
                    {
                        fItemTable.RejectChangesAll();
                        fItemTable.RefreshDetails();
                    }
                    catch { /* TODO: Log item restoration failures. */ }
                }
                throw;
            }
            finally
            {
                fItemTable.EventsDisabled = false;
            }
            fItemTable.UpdateCurrentRow();
            return new TableSetResult(TableSetResultStatus.Success, RowId, null);
        }
        catch (Exception Error)
        {
            return new TableSetResult(Committed ? TableSetResultStatus.AfterCommitFailed : TableSetResultStatus.DeleteFailed, RowId, Error);
        }
    }
    /// <summary>
    /// Saves the item tree in one transaction.
    /// Returns the outcome, ID and any exception, including failures after the database commits.
    /// </summary>
    public TableSetResult Commit(bool Reselect)
    {
        bool Committed = false;
        object RowId = null;
        try
        {
            if (fItemTable.Rows.Count != 1 || fItemTable.Rows[0].RowState == DataRowState.Deleted)
                throw new InvalidOperationException("The item table must contain one active row to commit.");

            List<(DataRow Row, DataColumn Column, object Value)> PreviousValues = new();
            fItemTable.EventsDisabled = true;
            try
            {
                NotifyTransactionStageCommit(null, TransactionStage.Start, ExecTime.Before);
                using (SqlTransactionContext Context = fStore.BeginTransactionContext())
                {
                    DbTransaction Transaction = Context.Transaction;
                    try
                    {
                        NotifyTransactionStageCommit(Transaction, TransactionStage.Start, ExecTime.After);
                        NotifyTransactionStageCommit(Transaction, TransactionStage.Post, ExecTime.Before);
                        List<MemTable> Tables = fItemTable.GetTreeAsFlatList();
                        CheckItemSaveTables(Tables);
                        foreach (MemTable Table in GetDeleteOrder(Tables))
                            PostDeletes(Transaction, Table, Table.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Deleted).ToArray());
                        foreach (MemTable Table in Tables.OrderBy(Item => Item.Level))
                            PostUpdates(Transaction, Table, Table.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Modified).ToArray());
                        foreach (MemTable Table in Tables.OrderBy(Item => Item.Level))
                            PostInserts(Transaction, Table, Table.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Added).ToArray(), PreviousValues, true);
                        NotifyTransactionStageCommit(Transaction, TransactionStage.Post, ExecTime.After);
                        NotifyTransactionStageCommit(Transaction, TransactionStage.Commit, ExecTime.Before);
                        Context.Commit();
                        Committed = true;
                        RowId = fItemTable.Rows[0][fItemTable.KeyField];
                        fItemTable.AcceptChangesAll();
                        NotifyTransactionStageCommit(Transaction, TransactionStage.Commit, ExecTime.After);
                    }
                    catch
                    {
                        if (Context.IsActive)
                        {
                            try { NotifyTransactionStageCommit(Transaction, TransactionStage.Rollback, ExecTime.Before); }
                            catch { /* TODO: Log rollback notification failures. */ }
                            bool RolledBack = false;
                            try
                            {
                                Context.Rollback();
                                RolledBack = true;
                            }
                            catch { /* TODO: Log rollback failures. */ }
                            if (RolledBack)
                            {
                                for (int Index = PreviousValues.Count - 1; Index >= 0; Index--)
                                {
                                    try { PreviousValues[Index].Row[PreviousValues[Index].Column] = PreviousValues[Index].Value; }
                                    catch { /* TODO: Log identifier restoration failures. */ }
                                }
                                try { NotifyTransactionStageCommit(Transaction, TransactionStage.Rollback, ExecTime.After); }
                                catch { /* TODO: Log rollback notification failures. */ }
                            }
                        }
                        throw;
                    }
                }
            }
            finally
            {
                fItemTable.EventsDisabled = false;
            }

            if (Reselect)
            {
                TableSetResult LoadResult = Load(RowId);
                if (LoadResult.Status == TableSetResultStatus.LoadFailed)
                    ExceptionDispatchInfo.Capture(LoadResult.Exception).Throw();
                if (LoadResult.Status != TableSetResultStatus.Success)
                    throw new InvalidOperationException("The committed item could not be reloaded.");
            }
            fItemTable.UpdateCurrentRow();
            return new TableSetResult(TableSetResultStatus.Success, RowId, null);
        }
        catch (Exception Error)
        {
            return new TableSetResult(Committed ? TableSetResultStatus.AfterCommitFailed : TableSetResultStatus.CommitFailed, RowId, Error);
        }
    }

    // ● item edit operations
    /// <summary>
    /// Cancels pending edits and clears the item table and all its details.
    /// This only affects the in-memory item tree; it does not access the database.
    /// </summary>
    public void ProcessEmpty()
    {
        CancelPendingEdits();
        fItemTable.EventsDisabled = true;
        try
        {
            fItemTable.ClearAll();
        }
        finally
        {
            fItemTable.EventsDisabled = false;
        }
        fItemTable.UpdateCurrentRow();
    }
    /// <summary>
    /// Clears the item tree and prepares one new top row for insertion.
    /// This only affects the in-memory item tree; it does not access the database.
    /// </summary>
    public void ProcessInsert()
    {
        ProcessEmpty();
        fItemTable.EventsDisabled = true;
        try
        {
            fItemTable.AddNewRow();
        }
        finally
        {
            fItemTable.EventsDisabled = false;
        }
        fItemTable.UpdateCurrentRow();
    }
    /// <summary>
    /// Accepts changes in the item table and its detail tree in memory.
    /// This does not save changes to the database.
    /// </summary>
    public void AcceptChanges() => fItemTable.AcceptChangesAll();
    /// <summary>
    /// Rejects changes in the item table and its detail tree in memory.
    /// This does not modify the database.
    /// </summary>
    public void RejectChanges() => fItemTable.RejectChangesAll();
    /// <summary>
    /// Returns whether the in-memory item table or any of its details has changes.
    /// This does not query the database.
    /// </summary>
    public bool HasChanges() => fItemTable.HasChangesAll();

    // ● events
    /// <summary>
    /// Occurs before and after transaction stages during item commit.
    /// After Commit has completed, an exception cannot undo the database commit.
    /// </summary>
    public event EventHandler<TransactionEventArgs> TransactionStageCommit;
    /// <summary>
    /// Occurs before and after transaction stages during item deletion.
    /// After Commit has completed, an exception cannot undo the database deletion.
    /// </summary>
    public event EventHandler<TransactionEventArgs> TransactionStageDelete;
}
